let state=loadProgress(), route='home', selectedRecipeId='alfredo', selectedCategory='brasileira', selectedWineId='pinot-grigio', recipeStage=0, recipeTab='lesson', lessonTab='learn', lessonStage=Math.min(Math.max(state.stage||0,0),stages.length-1), prepMode=!state.mise, qIndex=Number.isInteger(state.questionCurrent)?state.questionCurrent:0, examStatus=state.examStatus||'intro', audioStatus='idle', timerValue=0,timerInterval=null,timerRunning=false;
