function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pct(){return Math.round(state.done.length/stages.length*100)}
function btn(text,action,cls='btn btn-red',extra=''){return '<button class="'+cls+'" data-action="'+action+'" '+extra+'>'+text+'</button>'}function recipeVisual(id){const map={alfredo:'assets/module-alfredo.svg',arrabbiata:'assets/module-arrabbiata.svg',pesto:'assets/module-pesto.svg','ragù':'assets/module-ragu.svg',sauces:'assets/module-sauces.svg'};return map[id]||'assets/massas-italianas.jpg'}
