function audioPlayer(label,text){return '<section class="audio-card"><div class="audio-mark" aria-hidden="true">♫</div><div class="audio-main"><div class="audio-heading"><strong>'+label+'</strong><span class="audio-status" data-audio-state>'+statusText()+'</span></div><div class="audio-buttons"><button class="audio-control audio-play" data-action="audio-play" data-text="'+esc(text)+'" aria-label="Reproduzir áudio">▶</button><button class="audio-control" data-action="audio-pause" aria-label="Pausar áudio">Ⅱ</button><button class="audio-control" data-action="audio-resume" aria-label="Continuar áudio">▶</button><button class="audio-control" data-action="audio-replay" data-text="'+esc(text)+'" aria-label="Ouvir novamente">↻</button><label class="audio-volume"><span>Volume</span><input type="range" min="0" max="1" step=".05" value="'+(state.voiceVolume||.82)+'" data-audio-volume aria-label="Controle de volume"><span data-volume-value>'+Math.round((state.voiceVolume||.82)*100)+'%</span></label></div><details class="caption-details"><summary>Legenda</summary><p>'+esc(text)+'</p></details></div></section>'}
