function recipeReviewPage(){const r=extraRecipes.find(x=>x.id===selectedRecipeId);if(!r)return coursePage();return '<main class="page-wrap recipe-page"><button class="back-crumb" data-action="recipe-back">← Voltar à aula</button><section class="page-intro"><span class="eyebrow">REVISÃO · '+esc(r.title.toUpperCase())+'</span><h1>O caderno do Chef</h1><p>'+esc(r.chefTip)+'</p></section><div class="review-grid">'+r.techniques.map((x,i)=>'<article class="review-card"><span class="review-num">'+(i+1)+'</span><h3>'+esc(x)+'</h3><p>Releia as etapas correspondentes e observe como esta técnica aparece na preparação.</p></article>').join('')+'</div><h2>Erros comuns e correções</h2><div class="review-grid">'+r.errors.map(x=>'<article class="review-card"><p>'+esc(x)+'</p></article>').join('')+'</div>'+btn('Voltar ao módulo','recipe-back','btn btn-red')+'</main>'}
