function render(){stopTimerOnRouteChange();document.body.classList.toggle('has-demo-nav',!!state.demo);document.body.classList.toggle('is-wine-route',route==='wine'||route==='category-vinicola');let pages={home:home,sales:salesPage,chef:chefPage,categories:futureCategoryPage,'wine':winePage,'category-brasileira':futureCategoryPage,'category-japonesa':futureCategoryPage,'category-espanhola':futureCategoryPage,'category-francesa':futureCategoryPage,'category-internacional':futureCategoryPage,'category-vinicola':futureCategoryPage,courses:coursePage,course:coursePage,lesson:lesson,recipe:recipePage,recipeReview:recipeReviewPage,questions:questionView,review:review,exam:examPage,certificate:certificate,progress:progressPage,account:accountPage,help:helpPage};app.innerHTML=((route==='wine'||route==='category-vinicola')?wineHeader():header())+(pages[route]||home)();bind();}
function stopTimerOnRouteChange(){if(route!=='lesson'&&timerInterval){clearInterval(timerInterval);timerInterval=null;timerRunning=false}}
function clickHandler(e){const b=e.target.closest('[data-action]');if(b&&b.tagName==='A')e.preventDefault();if(!b)return;const a=b.dataset.action;if(a==='home')go('home');else if(a==='lesson-tab'){lessonTab=b.dataset.tab||'learn';render()}else if(a==='wine-scroll'){document.querySelector('#wine-selection')?.scrollIntoView({behavior:'smooth',block:'start'})}else if(a==='wine-scroll-back'||a==='wine-scroll-forward'){const i=wineProfiles.findIndex(x=>x.id===selectedWineId),step=a==='wine-scroll-back'?-1:1;selectedWineId=wineProfiles[(i+step+wineProfiles.length)%wineProfiles.length].id;render()}else if(a==='wine-discover'){const picker=$('#wine-picker');if(picker){selectedWineId=picker.value;go('wine')}}else if(a==='course')go('sales');else if(a==='sales')go('sales');else if(a==='chef')go('chef');else if(a==='category-future')go('categories');else if(a==='category-open'){selectedCategory=b.dataset.category;route='category-'+selectedCategory;render()}else if(a==='wine-open'){selectedWineId=b.dataset.wine;go('wine')}else if(a==='courses')go('courses');else if(a==='open-recipe'){selectedRecipeId=b.dataset.recipe;recipeStage=(state.recipeProgress?.[selectedRecipeId]?.stage)||0;recipeTab='lesson';go('recipe')}else if(a==='recipe-tab'){const r=extraRecipes.find(x=>x.id===selectedRecipeId);if(r){const p=recipeProgressFor(r);if(b.dataset.tab==='exam'&&(p.done.length<r.steps.length||!p.reviewDone)){showModal('Conclua e revise o módulo primeiro.','A prova fica disponível depois de percorrer todas as etapas e abrir a revisão.');return}recipeTab=b.dataset.tab;if(recipeTab==='exam'&&p.examStatus==='result')p.examStatus='intro'}render()}else if(a==='recipe-review-detail'){showModal(b.dataset.title||'Revisão',b.dataset.copy||'')}else if(a==='recipe-review-complete'){const p=recipeProgressFor(extraRecipes.find(x=>x.id===selectedRecipeId));p.reviewDone=true;persist();render()}else if(a==='recipe-exam-start'){const p=recipeProgressFor(extraRecipes.find(x=>x.id===selectedRecipeId));p.examAnswers=[];p.examCurrent=0;p.examStatus='active';persist();render()}else if(a==='recipe-answer'){const r=extraRecipes.find(x=>x.id===selectedRecipeId),p=recipeProgressFor(r);const arr=b.dataset.mode==='exam'?p.examAnswers:p.workAnswers;const ix=b.dataset.mode==='exam'?p.examCurrent:p.workCurrent;arr[ix]=+b.dataset.answer;persist();render()}else if(a==='recipe-question-next'){const r=extraRecipes.find(x=>x.id===selectedRecipeId),p=recipeProgressFor(r),mode=b.dataset.mode,examMode=mode==='exam',bank=recipeQuestionSet(r,examMode?8:6),idx=examMode?p.examCurrent:p.workCurrent,answers=examMode?p.examAnswers:p.workAnswers;if(answers[idx]==null)return;if(idx<bank.length-1){if(examMode)p.examCurrent++;else p.workCurrent++}else if(examMode)p.examStatus='review';else{const score=answers.filter((v,k)=>v===bank[k].correct).length;p.workAttempts.push({score,answers:answers.slice(),date:new Date().toISOString()});p.workFinished=true}persist();render()}else if(a==='recipe-question-back'){const p=recipeProgressFor(extraRecipes.find(x=>x.id===selectedRecipeId));if(b.dataset.mode==='exam')p.examCurrent=Math.max(0,p.examCurrent-1);else p.workCurrent=Math.max(0,p.workCurrent-1);render()}else if(a==='recipe-work-retry'){const p=recipeProgressFor(extraRecipes.find(x=>x.id===selectedRecipeId));p.workAnswers=[];p.workCurrent=0;p.workFinished=false;persist();render()}else if(a==='recipe-exam-edit'){const p=recipeProgressFor(extraRecipes.find(x=>x.id===selectedRecipeId));p.examCurrent=+b.dataset.question;p.examStatus='active';render()}else if(a==='recipe-exam-back'){const p=recipeProgressFor(extraRecipes.find(x=>x.id===selectedRecipeId));p.examStatus='active';render()}else if(a==='recipe-exam-submit'){openModal('<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><span class="eyebrow">CONFIRMAÇÃO</span><h2>Enviar sua prova?</h2><p>Depois do envio, exibiremos seu resultado e as explicações.</p><div class="modal-buttons"><button class="btn btn-outline-dark" data-action="close-modal">Ainda não</button><button class="btn btn-red" data-action="recipe-exam-confirm">Confirmar envio</button></div></section></div>')}else if(a==='recipe-exam-confirm'){closeModal();const r=extraRecipes.find(x=>x.id===selectedRecipeId),p=recipeProgressFor(r),bank=recipeQuestionSet(r,8),right=p.examAnswers.filter((v,k)=>v===bank[k].correct).length,score=Math.round(right/8*100);p.examAttempts.push({score,passed:score>=70,answers:p.examAnswers.slice(),date:new Date().toISOString()});p.examStatus='result';p.examAnswers=[];p.examCurrent=0;persist();render()}else if(a==='recipe-step'){recipeStage=+b.dataset.step;const p=recipeProgressFor(extraRecipes.find(x=>x.id===selectedRecipeId));p.stage=recipeStage;persist();render()}else if(a==='recipe-prev'){recipeStage=Math.max(0,recipeStage-1);render()}else if(a==='recipe-next'){const r=extraRecipes.find(x=>x.id===selectedRecipeId);state.recipeProgress=state.recipeProgress||{};state.recipeProgress[selectedRecipeId]=state.recipeProgress[selectedRecipeId]||{done:[]};let done=state.recipeProgress[selectedRecipeId].done;if(recipeStage>0&&!done.includes(recipeStage-1)&&!done.includes(recipeStage)){showModal('Vamos uma etapa de cada vez.','Conclua a etapa anterior antes de marcar esta como pronta.');return}if(!done.includes(recipeStage))done.push(recipeStage);if(recipeStage<r.steps.length-1)recipeStage++;state.recipeProgress[selectedRecipeId].stage=recipeStage;persist();render()}else if(a==='recipe-review')go('recipeReview');else if(a==='recipe-back')go('recipe');else if(a==='lesson')startCourse();else if(a==='start-course')startCourse();else if(a==='account')go('account');else if(a==='progress')go('progress');else if(a==='certificate'){if(state.examAttempts.some(x=>x.passed))examStatus='certificate';go('certificate')}else if(a==='exam'){if(!state.lessonFinished||!state.reviewDone){showModal('A prova será liberada depois da revisão.','Conclua as seis etapas e marque a revisão como concluída antes de iniciar a avaliação.');return}examStatus='intro';go('exam')}else if(a==='help')go('help');else if(a==='questions')go('questions');else if(a==='review')go('review');else if(a==='review-complete'){state.reviewDone=true;persist();render()}else if(a==='review-detail'){const x=reviewItems[+b.dataset.review];if(x)showModal(x[0],x[1])}else if(a==='lesson-play'){const x=stages[lessonStage];playText(x.audioScript||x.title+'. '+x.intro+' '+x.tip)}else if(a==='sos')showSos();else if(a==='sos-choice')showSosAnswer(+b.dataset.choice);else if(a==='eye')showEye();else if(a==='intro-play')playText(introText);else if(a==='audio-play'||a==='audio-replay')playText(b.dataset.text);else if(a==='audio-pause'){pauseChef();audioStatus='paused';updateAudioStatus()}else if(a==='audio-resume'){resumeChef();audioStatus='playing';updateAudioStatus()}else if(a==='jump-step'){if(timerInterval)timerPause();stopChef();lessonStage=+b.dataset.step;state.stage=lessonStage;persist();render()}else if(a==='lesson-next')nextLesson();else if(a==='lesson-prev'){if(lessonStage>0){lessonStage--;state.stage=lessonStage;persist();render()}}else if(a==='mise-ready'){state.mise=true;state.demo=true;prepMode=false;persist();render()}else if(a==='question-answer')answerLearning(+b.dataset.answer);else if(a==='question-next')nextLearning();else if(a==='questions-retry'){state.questionsAnswers=[];state.questionsFinished=false;qIndex=0;persist();render()}else if(a==='start-exam'){if(!state.lessonFinished||!state.reviewDone){showModal('Quase lá!','Conclua as seis etapas e marque a revisão como concluída para liberar a avaliação final.');return}examStatus='intro';persist();go('exam')}else if(a==='begin-exam')beginExam();else if(a==='exam-answer'){state.examAnswers[state.examCurrent]=+b.dataset.answer;persist();render()}else if(a==='exam-next'){if(state.examAnswers[state.examCurrent]==null)return;if(state.examCurrent<exam.length-1){state.examCurrent++;persist();render()}else{examStatus='review';persist();render()}}else if(a==='exam-back'){if(state.examCurrent>0){state.examCurrent--;render()}}else if(a==='exam-edit'){state.examCurrent=+b.dataset.question;examStatus='question';persist();render()}else if(a==='submit-exam')confirmExam();else if(a==='confirm-submit')submitExam();else if(a==='retry-exam'){examStatus='retryIntro';persist();go('exam')}else if(a==='timer-start')timerStart();else if(a==='timer-pause')timerPause();else if(a==='timer-reset')timerReset();else if(a==='reset-demo')resetDemo();else if(a==='demo-entry'){closeModal();state.demo=true;persist();go('courses')}else if(a==='close-modal')closeModal()}
function go(next){stopChef();audioStatus='idle';if(next==='account'&&!state.demo){route='account';render();return}if(next==='progress'&&!state.demo){route='progress';render();return}if(next==='certificate'&&!state.demo){route='certificate';render();return}if(next==='questions'&&!state.demo){openDemoModal('Para experimentar as perguntas, abra o curso em modo demonstração.');return}if(next==='review'&&!state.demo){openDemoModal('A revisão fica disponível no modo demonstração.');return}route=next;render()}
function startCourse(){stopChef();lessonTab='learn';state.demo=true;route='lesson';lessonStage=Math.min(state.stage||0,5);prepMode=false;persist();render()}
function nextLesson(){if(lessonStage>0&&state.done.indexOf(lessonStage-1)<0&&state.done.indexOf(lessonStage)<0){showModal('Vamos uma etapa de cada vez.','Conclua a etapa anterior antes de marcar esta como pronta. Você pode consultar qualquer explicação, mas o progresso da aula segue em ordem.');return}if(state.done.indexOf(lessonStage)<0)state.done.push(lessonStage);state.stage=lessonStage;persist();if(lessonStage===stages.length-1){state.lessonFinished=true;persist();openCompletion()}else{lessonStage++;state.stage=lessonStage;persist();render()}}
function answerLearning(choice){if(state.questionsAnswers[qIndex]!==undefined)return;state.questionsAnswers[qIndex]=choice;state.demo=true;persist();render()}
function nextLearning(){if(qIndex<questions.length-1){qIndex++;persist();render();return}const correct=state.questionsAnswers.filter((v,i)=>v===questions[i].correct).length;state.questionAttempts.push({score:correct,answers:state.questionsAnswers.slice(),date:new Date().toISOString()});state.questionsFinished=true;state.demo=true;persist();render()}
function beginExam(){state.demo=true;state.examAnswers=Array(exam.length).fill(null);state.examCurrent=0;state.examReview=false;examStatus='question';persist();route='exam';render()}
function confirmExam(){if(state.examAnswers.some(x=>x==null)){showModal('Faltou uma resposta','Volte e escolha uma alternativa para cada pergunta antes de enviar.');return}modal.innerHTML='<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><span class="eyebrow">CONFIRMAÇÃO</span><h2>Enviar sua avaliação?</h2><p>Depois do envio, mostramos seu resultado e as explicações.</p><div class="modal-buttons"><button class="btn btn-outline-dark" data-action="close-modal">Ainda não</button><button class="btn btn-red" data-action="confirm-submit">Confirmar envio</button></div></section></div>'}
function submitExam(){let answers=state.examAnswers.slice(),right=answers.filter((v,i)=>v===exam[i].correct).length,score=Math.round(right/exam.length*100);state.examAttempts.push({score,passed:score>=70,answers:answers,date:new Date().toISOString()});state.examAnswers=[];state.examCurrent=0;state.examReview=false;examStatus='result';persist();render()}

function examResult(){const result=state.examAttempts[state.examAttempts.length-1]||{score:0,passed:false,answers:[]};return '<main class="page-wrap">'+courseBanner('exam')+'<section class="result-card"><span class="eyebrow">RESULTADO DA AVALIAÇÃO</span><div class="result-medal">'+result.score+'%</div><h2>'+(result.passed?'PARABÉNS! VOCÊ CONSEGUIU!':'Não desanime! Vamos revisar juntos e tentar novamente.')+'</h2><p>'+(result.passed?'Você concluiu sua avaliação! Seu aprendizado merece ser comemorado.':'A nota mínima é 70%. Reveja as etapas e tente outra vez; novas tentativas estão liberadas.')+'</p><div class="answer-review-list">'+exam.map((q,i)=>'<article class="review-answer"><span class="review-mark">'+(result.answers[i]===q.correct?'✓':'↺')+'</span><div><strong>'+esc(q.q)+'</strong><p>Sua resposta: '+esc(q.a[result.answers[i]??0])+'</p><small>Correta: '+esc(q.a[q.correct])+'</small><p class="exam-explain">'+esc(q.why)+'</p></div></article>').join('')+'</div>'+btn(result.passed?'Ver certificado':'Revisar conteúdo',result.passed?'certificate':'review',result.passed?'btn btn-saffron':'btn btn-outline-dark')+' '+btn('Tentar novamente','retry-exam','text-action')+'</section>'+footerNote()+'</main>'}
function timerStart(){if(timerInterval)return;const field=$('[data-timer-input]');if(!timerValue){let m=field?parseInt(field.value,10):0;if(!Number.isFinite(m)||m<1||m>180){if(field)field.focus();return}timerValue=m*60}timerRunning=true;timerInterval=setInterval(()=>{timerValue=Math.max(0,timerValue-1);let el=$('[data-timer]');if(el)el.textContent=formatTime(timerValue);if(timerValue<=0){clearInterval(timerInterval);timerInterval=null;timerRunning=false;let label=$('.timer-card .eyebrow');if(label)label.textContent='TEMPO DA EMBALAGEM · CONFIRA O PONTO';}},1000);renderTimerButtons()}
function renderTimerButtons(){const b=$('[data-action="timer-start"]');if(b)b.textContent=timerRunning?'Rodando…':'Retomar'}
function timerPause(){if(timerInterval){clearInterval(timerInterval);timerInterval=null}timerRunning=false;renderTimerButtons()}
function timerReset(){timerPause();timerValue=0;let d=$('[data-timer]');if(d)d.textContent=formatTime(0);let i=$('[data-timer-input]');if(i)i.value=''}
function playText(text){audioStatus='loading';updateAudioStatus();playChef(text,s=>{audioStatus=s;updateAudioStatus()})}
function updateAudioStatus(){document.querySelectorAll('[data-audio-state]').forEach(x=>x.textContent=statusText())}
function showSos(){const choices=['Não entendi esta etapa.','Minha preparação ficou diferente.','Não sei identificar o ponto correto.','Quero uma explicação mais simples.','Quero entender um erro comum.','Preciso revisar uma técnica.'];openModal('<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><span class="eyebrow">SOCORRO, CHEF! · ETAPA '+(lessonStage+1)+'</span><h2>Vamos resolver juntos.</h2><p>Escolha o que está acontecendo. Esta ajuda é uma orientação preparada para a etapa, não uma conversa com IA.</p>'+choices.map((x,i)=>'<button class="assist-choice" data-action="sos-choice" data-choice="'+i+'">'+x+'</button>').join('')+'<div class="answer hide" data-sos-answer></div></section></div>')}
function showSosAnswer(i){const s=stages[lessonStage],texts=['Vamos por partes. '+s.intro+' '+s.body,'Tudo bem, cada cozinha tem seu ritmo. '+s.tip,'Observe o sinal importante desta etapa: '+s.tip,'Em poucas palavras: '+s.intro+' '+s.tip,'Um erro comum nesta etapa é ignorar o calor e o ponto. '+s.warning,'Vamos revisar o fundamento: '+s.body];const el=modal.querySelector('[data-sos-answer]');if(el){el.classList.remove('hide');el.innerHTML='<strong>Dica do Chef para '+esc(s.tag)+':</strong><br>'+esc(texts[i]||s.tip)+'<br><br>Seu progresso continua guardado.'}}
function showEye(){const s=stages[lessonStage];openModal('<div class="modal-backdrop"><section class="modal eye-modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><span class="eyebrow">OLHO DO CHEF · '+esc(s.tag)+'</span><h2>Repare nos detalhes.</h2><img src="'+s.photo+'" alt="'+esc(s.alt)+'" class="eye-photo"><span class="photo-caption-inline">'+esc(s.caption)+'</span><div class="eye-observation"><strong>O que observar</strong><p>'+esc(s.tip)+'</p></div><div class="safety-note"><strong>Fique atenta:</strong> '+esc(s.warning)+'</div><p class="small-note">A imagem mostra o resultado ou procedimento de apoio; não é uma fotografia de erro para comparação.</p></section></div>')}
function openModal(html){modal.innerHTML=html;modal.querySelectorAll('.modal-backdrop').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)closeModal()}))}
function closeModal(){modal.innerHTML=''}
function showModal(title,copy){openModal('<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><span class="eyebrow">FERVEC GASTRONOMIA</span><h2>'+esc(title)+'</h2><p>'+esc(copy)+'</p><button class="btn btn-red" data-action="close-modal">Entendi</button></section></div>')}
function openDemoModal(copy){openModal('<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><span class="eyebrow">MODO DEMONSTRAÇÃO</span><h2>Vamos para a cozinha?</h2><p>'+esc(copy)+'</p><div class="modal-callout">Esta versão guarda o progresso só neste navegador. Não cria conta, compra, matrícula ou certificado oficial.</div><div class="modal-buttons"><button class="btn btn-red" data-action="demo-entry">Explorar a demonstração</button><button class="btn btn-outline-dark" data-action="close-modal">Voltar</button></div></section></div>')}
function openCompletion(){openModal('<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><span class="eyebrow">MAIS UMA ETAPA CONCLUÍDA!</span><h2>Parabéns pela sua Carbonara!</h2><p>Você percorreu as seis etapas. Seu avanço está salvo nesta demonstração.</p><div class="modal-buttons"><button class="btn btn-outline-dark" data-action="close-modal">Voltar para a aula</button><button class="btn btn-red" data-action="questions">Ir às perguntas</button></div></section></div>')}
function resetDemo(){openModal('<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal">×</button><span class="eyebrow">DADOS DESTE NAVEGADOR</span><h2>Apagar seu progresso?</h2><p>Isso remove o progresso, as respostas e as tentativas locais desta demonstração. A ação não pode ser desfeita.</p><div class="modal-buttons"><button class="btn btn-outline-dark" data-action="close-modal">Manter progresso</button><button class="btn btn-red" data-action="confirm-reset">Apagar dados</button></div></section></div>');modal.addEventListener('click',function(e){let b=e.target.closest('[data-action="confirm-reset"]');if(b){clearProgress();state=loadProgress();closeModal();route='home';render() }},{once:true})}
function bind(){app.querySelectorAll('[data-micro]').forEach(el=>el.addEventListener('change',()=>setMicroDone(lessonStage,+el.dataset.micro,el.checked)));app.querySelectorAll('[data-mise]').forEach(el=>el.addEventListener('change',()=>{let n=+el.dataset.mise;state.miseChecks=el.checked?Array.from(new Set(state.miseChecks.concat([n]))):state.miseChecks.filter(x=>x!==n);persist()}));app.querySelectorAll('[data-timer-input]').forEach(el=>el.addEventListener('input',()=>{timerValue=0;let d=$('[data-timer]');if(d)d.textContent=formatTime(0)}));app.querySelectorAll('[data-audio-volume]').forEach(el=>el.addEventListener('input',()=>{state.voiceVolume=Number(el.value);setChefVolume(state.voiceVolume);let label=el.parentElement.querySelector('[data-volume-value]');if(label)label.textContent=Math.round(state.voiceVolume*100)+'%';persist()}))};
app.addEventListener('click',clickHandler);
modal.addEventListener('click',clickHandler);
render();
